// Filter utility functions
import type { Project, FilterState, Technology, Category } from '../types';

export const filterProjects = (
  projects: Project[],
  filters: FilterState
): Project[] => {
  return projects.filter(project => {
    // Search query filter
    if (filters.searchQuery) {
      const query = filters.searchQuery.toLowerCase();
      const matchesTitle = project.title.toLowerCase().includes(query);
      const matchesDescription = project.description.toLowerCase().includes(query);
      const matchesLongDescription = project.longDescription?.toLowerCase().includes(query);
      const matchesTech = project.technologies.some(tech =>
        tech.name.toLowerCase().includes(query)
      );
      const matchesCategory = project.category.name.toLowerCase().includes(query);
      
      if (!matchesTitle && !matchesDescription && !matchesLongDescription && !matchesTech && !matchesCategory) {
        return false;
      }
    }

    // Technology filter
    if (filters.technologies.length > 0) {
      const projectTechIds = project.technologies.map(tech => tech.id);
      const hasMatchingTech = filters.technologies.some(techId =>
        projectTechIds.includes(techId)
      );
      if (!hasMatchingTech) {
        return false;
      }
    }

    // Category filter
    if (filters.categories.length > 0) {
      if (!filters.categories.includes(project.category.id)) {
        return false;
      }
    }

    // Status filter
    if (filters.status.length > 0) {
      if (!filters.status.includes(project.status)) {
        return false;
      }
    }

    return true;
  });
};

// Get unique technologies from projects
export const getUniqueTechnologies = (projects: Project[]): Technology[] => {
  const techMap = new Map<string, Technology>();
  
  projects.forEach(project => {
    project.technologies.forEach(tech => {
      if (!techMap.has(tech.id)) {
        techMap.set(tech.id, tech);
      }
    });
  });
  
  return Array.from(techMap.values()).sort((a, b) => a.name.localeCompare(b.name));
};

// Get unique categories from projects
export const getUniqueCategories = (projects: Project[]): Category[] => {
  const categoryMap = new Map<string, Category>();
  
  projects.forEach(project => {
    if (!categoryMap.has(project.category.id)) {
      categoryMap.set(project.category.id, project.category);
    }
  });
  
  return Array.from(categoryMap.values()).sort((a, b) => a.order - b.order);
};

// Generate search suggestions based on projects
export const generateSearchSuggestions = (projects: Project[]): string[] => {
  const suggestions = new Set<string>();
  
  projects.forEach(project => {
    // Add project titles
    suggestions.add(project.title);
    
    // Add technology names
    project.technologies.forEach(tech => {
      suggestions.add(tech.name);
    });
    
    // Add category names
    suggestions.add(project.category.name);
    
    // Add common words from descriptions (longer than 3 characters)
    const words = project.description.split(/\s+/).filter(word => 
      word.length > 3 && /^[a-zA-Z]+$/.test(word)
    );
    words.forEach(word => suggestions.add(word));
  });
  
  return Array.from(suggestions).sort();
};

// Check if filters match any projects
export const hasMatchingProjects = (projects: Project[], filters: FilterState): boolean => {
  return filterProjects(projects, filters).length > 0;
};

// Get filter summary for display
export const getFilterSummary = (
  filters: FilterState,
  technologies: Technology[],
  categories: Category[]
): string => {
  const parts: string[] = [];
  
  if (filters.searchQuery) {
    parts.push(`"${filters.searchQuery}"`);
  }
  
  if (filters.technologies.length > 0) {
    const techNames = filters.technologies
      .map(id => technologies.find(t => t.id === id)?.name)
      .filter(Boolean);
    parts.push(`Technologies: ${techNames.join(', ')}`);
  }
  
  if (filters.categories.length > 0) {
    const categoryNames = filters.categories
      .map(id => categories.find(c => c.id === id)?.name)
      .filter(Boolean);
    parts.push(`Categories: ${categoryNames.join(', ')}`);
  }
  
  if (filters.status.length > 0) {
    const statusLabels = filters.status.map(status => {
      switch (status) {
        case 'active': return 'Active';
        case 'in-progress': return 'In Progress';
        case 'archived': return 'Archived';
        default: return status;
      }
    });
    parts.push(`Status: ${statusLabels.join(', ')}`);
  }
  
  return parts.join(' • ');
};

// Highlight search terms in text
export const highlightSearchTerms = (text: string, searchQuery: string): string => {
  if (!searchQuery.trim()) return text;
  
  const escapedQuery = searchQuery.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const regex = new RegExp(`(${escapedQuery})`, 'gi');
  return text.replace(regex, '<mark>$1</mark>');
};

// Additional utility functions for enhanced filtering

// Get filter statistics for display
export const getFilterStats = (
  allProjects: Project[],
  filteredProjects: Project[],
  filters: FilterState
): {
  total: number;
  filtered: number;
  percentage: number;
  hasFilters: boolean;
} => {
  const hasFilters = 
    filters.searchQuery.length > 0 ||
    filters.technologies.length > 0 ||
    filters.categories.length > 0 ||
    filters.status.length > 0;

  return {
    total: allProjects.length,
    filtered: filteredProjects.length,
    percentage: allProjects.length > 0 ? Math.round((filteredProjects.length / allProjects.length) * 100) : 0,
    hasFilters,
  };
};

// Get suggested filters based on current results
export const getSuggestedFilters = (
  projects: Project[],
  currentFilters: FilterState
): {
  technologies: Technology[];
  categories: Category[];
  statuses: string[];
} => {
  const availableTechnologies = getUniqueTechnologies(projects);
  const availableCategories = getUniqueCategories(projects);
  const availableStatuses = [...new Set(projects.map(p => p.status))];

  // Filter out already selected items
  const suggestedTechnologies = availableTechnologies.filter(
    tech => !currentFilters.technologies.includes(tech.id)
  );
  
  const suggestedCategories = availableCategories.filter(
    cat => !currentFilters.categories.includes(cat.id)
  );
  
  const suggestedStatuses = availableStatuses.filter(
    status => !currentFilters.status.includes(status)
  );

  return {
    technologies: suggestedTechnologies.slice(0, 5), // Limit suggestions
    categories: suggestedCategories.slice(0, 3),
    statuses: suggestedStatuses,
  };
};

// Create shareable URL with current filters
export const createShareableURL = (filters: FilterState, baseUrl?: string): string => {
  const url = new URL(baseUrl || window.location.origin + window.location.pathname);
  const params = new URLSearchParams();

  if (filters.searchQuery) {
    params.set('search', filters.searchQuery);
  }

  if (filters.technologies.length > 0) {
    params.set('technologies', filters.technologies.join(','));
  }

  if (filters.categories.length > 0) {
    params.set('categories', filters.categories.join(','));
  }

  if (filters.status.length > 0) {
    params.set('status', filters.status.join(','));
  }

  const queryString = params.toString();
  return queryString ? `${url.toString()}?${queryString}` : url.toString();
};

// Parse filters from URL search params
export const parseFiltersFromURL = (searchParams: URLSearchParams): Partial<FilterState> => {
  const filters: Partial<FilterState> = {};

  const search = searchParams.get('search');
  if (search) {
    filters.searchQuery = search;
  }

  const technologies = searchParams.get('technologies');
  if (technologies) {
    filters.technologies = technologies.split(',').filter(Boolean);
  }

  const categories = searchParams.get('categories');
  if (categories) {
    filters.categories = categories.split(',').filter(Boolean);
  }

  const status = searchParams.get('status');
  if (status) {
    filters.status = status.split(',').filter(Boolean);
  }

  return filters;
};

// Validate filter values against available options
export const validateFilters = (
  filters: FilterState,
  availableTechnologies: Technology[],
  availableCategories: Category[]
): FilterState => {
  const validTechIds = new Set(availableTechnologies.map(t => t.id));
  const validCategoryIds = new Set(availableCategories.map(c => c.id));
  const validStatuses = new Set(['active', 'in-progress', 'archived']);

  return {
    searchQuery: filters.searchQuery,
    technologies: filters.technologies.filter(id => validTechIds.has(id)),
    categories: filters.categories.filter(id => validCategoryIds.has(id)),
    status: filters.status.filter(status => validStatuses.has(status)),
  };
};

// Get filter breadcrumbs for navigation
export const getFilterBreadcrumbs = (
  filters: FilterState,
  technologies: Technology[],
  categories: Category[]
): Array<{
  type: 'search' | 'technology' | 'category' | 'status';
  label: string;
  value: string;
  onRemove: () => FilterState;
}> => {
  const breadcrumbs: Array<{
    type: 'search' | 'technology' | 'category' | 'status';
    label: string;
    value: string;
    onRemove: () => FilterState;
  }> = [];

  // Search query breadcrumb
  if (filters.searchQuery) {
    breadcrumbs.push({
      type: 'search',
      label: `Search: "${filters.searchQuery}"`,
      value: filters.searchQuery,
      onRemove: () => ({ ...filters, searchQuery: '' }),
    });
  }

  // Technology breadcrumbs
  filters.technologies.forEach(techId => {
    const tech = technologies.find(t => t.id === techId);
    if (tech) {
      breadcrumbs.push({
        type: 'technology',
        label: tech.name,
        value: techId,
        onRemove: () => ({
          ...filters,
          technologies: filters.technologies.filter(id => id !== techId),
        }),
      });
    }
  });

  // Category breadcrumbs
  filters.categories.forEach(categoryId => {
    const category = categories.find(c => c.id === categoryId);
    if (category) {
      breadcrumbs.push({
        type: 'category',
        label: category.name,
        value: categoryId,
        onRemove: () => ({
          ...filters,
          categories: filters.categories.filter(id => id !== categoryId),
        }),
      });
    }
  });

  // Status breadcrumbs
  filters.status.forEach(status => {
    const statusLabel = status === 'in-progress' ? 'In Progress' : 
                      status.charAt(0).toUpperCase() + status.slice(1);
    breadcrumbs.push({
      type: 'status',
      label: statusLabel,
      value: status,
      onRemove: () => ({
        ...filters,
        status: filters.status.filter(s => s !== status),
      }),
    });
  });

  return breadcrumbs;
};

// Advanced search with fuzzy matching
export const fuzzySearchProjects = (
  projects: Project[],
  searchQuery: string,
  threshold: number = 0.6
): Project[] => {
  if (!searchQuery.trim()) return projects;

  const query = searchQuery.toLowerCase();
  
  return projects
    .map(project => {
      let score = 0;
      let matches = 0;

      // Check title (highest weight)
      if (project.title.toLowerCase().includes(query)) {
        score += 10;
        matches++;
      }

      // Check description (medium weight)
      if (project.description.toLowerCase().includes(query)) {
        score += 5;
        matches++;
      }

      // Check long description (medium weight)
      if (project.longDescription?.toLowerCase().includes(query)) {
        score += 5;
        matches++;
      }

      // Check technologies (medium weight)
      project.technologies.forEach(tech => {
        if (tech.name.toLowerCase().includes(query)) {
          score += 3;
          matches++;
        }
      });

      // Check category (low weight)
      if (project.category.name.toLowerCase().includes(query)) {
        score += 2;
        matches++;
      }

      // Calculate relevance score
      const relevance = matches > 0 ? score / (query.length + project.title.length) : 0;

      return { project, relevance, matches };
    })
    .filter(item => item.relevance >= threshold)
    .sort((a, b) => b.relevance - a.relevance)
    .map(item => item.project);
};