/**
 * Image optimization utilities for responsive images and performance
 */

export interface ImageSizeConfig {
  width: number;
  quality?: number;
  format?: 'webp' | 'jpg' | 'png';
}

export interface ResponsiveImageConfig {
  src: string;
  sizes: ImageSizeConfig[];
  fallbackFormat?: 'jpg' | 'png';
}

/**
 * Generate responsive image srcSet from a base image URL
 * This would typically integrate with a CDN or image service like Cloudinary
 */
export const generateResponsiveSrcSet = (
  baseSrc: string,
  sizes: number[] = [400, 800, 1200, 1600],
  format: 'webp' | 'jpg' | 'png' = 'webp'
): string => {
  const lastDotIndex = baseSrc.lastIndexOf('.');
  const basePath = baseSrc.substring(0, lastDotIndex);
  const originalExtension = baseSrc.substring(lastDotIndex);
  
  // In a real application, this would generate URLs for a CDN service
  // For now, we'll simulate the pattern
  return sizes
    .map(size => {
      const extension = format === 'webp' ? '.webp' : originalExtension;
      return `${basePath}_${size}w${extension} ${size}w`;
    })
    .join(', ');
};

/**
 * Generate sizes attribute for responsive images based on breakpoints
 */
export const generateSizesAttribute = (
  breakpoints: Array<{ maxWidth: number; size: string }>,
  defaultSize: string = '100vw'
): string => {
  const mediaQueries = breakpoints
    .map(({ maxWidth, size }) => `(max-width: ${maxWidth}px) ${size}`)
    .join(', ');
  
  return `${mediaQueries}, ${defaultSize}`;
};

