/**
 * Preload critical images for better performance
 */
export const preloadImage = (src: string, priority: boolean = false): Promise<void> => {
  return new Promise((resolve, reject) => {
    const link = document.createElement('link');
    link.rel = 'preload';
    link.as = 'image';
    link.href = src;
    
    if (priority) {
      link.setAttribute('fetchpriority', 'high');
    }
    
    link.onload = () => resolve();
    link.onerror = () => reject(new Error(`Failed to preload image: ${src}`));
    
    document.head.appendChild(link);
  });
};

/**
 * Preload multiple images
 */
export const preloadImages = async (
  images: Array<{ src: string; priority?: boolean }>
): Promise<void> => {
  const promises = images.map(({ src, priority }) => 
    preloadImage(src, priority).catch(() => {
      console.warn(`Failed to preload image: ${src}`);
    })
  );
  
  await Promise.allSettled(promises);
};

/**
 * Check if WebP format is supported
 */
export const supportsWebP = (): Promise<boolean> => {
  return new Promise((resolve) => {
    const webP = new Image();
    webP.onload = webP.onerror = () => {
      resolve(webP.height === 2);
    };
    webP.src = 'data:image/webp;base64,UklGRjoAAABXRUJQVlA4IC4AAACyAgCdASoCAAIALmk0mk0iIiIiIgBoSygABc6WWgAA/veff/0PP8bA//LwYAAA';
  });
};

/**
 * Get optimal image format based on browser support
 */
export const getOptimalFormat = async (
  originalFormat: string = 'jpg'
): Promise<'webp' | 'jpg' | 'png'> => {
  const webpSupported = await supportsWebP();
  
  if (webpSupported) {
    return 'webp';
  }
  
  return originalFormat === 'png' ? 'png' : 'jpg';
};

/**
 * Calculate aspect ratio from dimensions
 */
export const calculateAspectRatio = (width: number, height: number): string => {
  const gcd = (a: number, b: number): number => {
    return b === 0 ? a : gcd(b, a % b);
  };
  
  const divisor = gcd(width, height);
  const aspectWidth = width / divisor;
  const aspectHeight = height / divisor;
  
  return `${aspectWidth} / ${aspectHeight}`;
};

/**
 * Image loading performance metrics
 */
export interface ImageLoadMetrics {
  loadTime: number;
  size: number;
  format: string;
  cached: boolean;
}

/**
 * Track image loading performance
 */
export const trackImageLoad = (src: string): Promise<ImageLoadMetrics> => {
  return new Promise((resolve, reject) => {
    const startTime = performance.now();
    const img = new Image();
    
    img.onload = () => {
      const loadTime = performance.now() - startTime;
      
      // Try to get image size (this is approximate)
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      canvas.width = img.naturalWidth;
      canvas.height = img.naturalHeight;
      ctx?.drawImage(img, 0, 0);
      
      // Estimate size (this is not accurate for actual file size)
      const imageData = ctx?.getImageData(0, 0, canvas.width, canvas.height);
      const estimatedSize = imageData ? imageData.data.length : 0;
      
      resolve({
        loadTime,
        size: estimatedSize,
        format: src.split('.').pop()?.toLowerCase() || 'unknown',
        cached: loadTime < 50 // Rough heuristic for cached images
      });
    };
    
    img.onerror = () => {
      reject(new Error(`Failed to load image: ${src}`));
    };
    
    img.src = src;
  });
};

/**
 * Batch image loading with concurrency control
 */
export const loadImagesWithConcurrency = async (
  imageSrcs: string[],
  maxConcurrency: number = 3
): Promise<ImageLoadMetrics[]> => {
  const results: ImageLoadMetrics[] = [];
  const executing: Promise<void>[] = [];
  
  for (const src of imageSrcs) {
    const promise = trackImageLoad(src)
      .then(metrics => {
        results.push(metrics);
      })
      .catch(error => {
        console.warn(`Failed to load image ${src}:`, error);
      });
    
    executing.push(promise);
    
    if (executing.length >= maxConcurrency) {
      await Promise.race(executing);
      executing.splice(executing.findIndex(p => p === promise), 1);
    }
  }
  
  await Promise.all(executing);
  return results;
};/**

 * Compress images client-side for uploads
 */
export function compressImage(
  file: File,
  options: {
    maxWidth?: number;
    maxHeight?: number;
    quality?: number;
    format?: 'jpeg' | 'webp' | 'png';
  } = {}
): Promise<Blob> {
  return new Promise((resolve, reject) => {
    const {
      maxWidth = 1920,
      maxHeight = 1080,
      quality = 0.8,
      format = 'jpeg'
    } = options;

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = new Image();

    if (!ctx) {
      reject(new Error('Canvas context not available'));
      return;
    }

    img.onload = () => {
      let { width, height } = img;
      
      // Calculate new dimensions maintaining aspect ratio
      if (width > maxWidth) {
        height = (height * maxWidth) / width;
        width = maxWidth;
      }
      
      if (height > maxHeight) {
        width = (width * maxHeight) / height;
        height = maxHeight;
      }

      canvas.width = width;
      canvas.height = height;

      ctx.drawImage(img, 0, 0, width, height);

      canvas.toBlob(
        (blob) => {
          if (blob) {
            resolve(blob);
          } else {
            reject(new Error('Failed to compress image'));
          }
        },
        `image/${format}`,
        quality
      );
    };

    img.onerror = () => reject(new Error('Failed to load image for compression'));
    img.src = URL.createObjectURL(file);
  });
}

/**
 * Preload critical images with priority hints
 */
export async function preloadCriticalImages(
  images: Array<{ src: string; priority?: 'high' | 'low' }>
): Promise<void> {
  const preloadPromises = images.map(({ src, priority = 'high' }) => {
    return new Promise<void>((resolve, reject) => {
      const link = document.createElement('link');
      link.rel = 'preload';
      link.as = 'image';
      link.href = src;
      link.fetchPriority = priority;
      
      link.onload = () => resolve();
      link.onerror = () => reject(new Error(`Failed to preload image: ${src}`));
      
      document.head.appendChild(link);
    });
  });

  try {
    await Promise.all(preloadPromises);
    console.log('Critical images preloaded successfully');
  } catch (error) {
    console.warn('Some critical images failed to preload:', error);
  }
}

/**
 * Monitor image loading performance
 */
export class ImagePerformanceMonitor {
  private metrics: Map<string, { loadTime: number; size?: number }> = new Map();

  async trackImageLoad(src: string): Promise<{ loadTime: number; size?: number }> {
    const startTime = performance.now();
    
    return new Promise((resolve, reject) => {
      const img = new Image();
      
      img.onload = () => {
        const loadTime = performance.now() - startTime;
        const metrics = { loadTime };
        this.metrics.set(src, metrics);
        resolve(metrics);
      };
      
      img.onerror = () => {
        reject(new Error(`Failed to load image: ${src}`));
      };
      
      img.src = src;
    });
  }

  getMetrics() {
    return Array.from(this.metrics.entries()).map(([src, metrics]) => ({
      src,
      ...metrics
    }));
  }

  getAverageLoadTime(): number {
    const metrics = Array.from(this.metrics.values());
    if (metrics.length === 0) return 0;
    
    const totalTime = metrics.reduce((sum, metric) => sum + metric.loadTime, 0);
    return totalTime / metrics.length;
  }

  clear(): void {
    this.metrics.clear();
  }
}

// Global image performance monitor instance
export const imagePerformanceMonitor = new ImagePerformanceMonitor();